def usage_for(opts, prog):
    if opts.check:
        return f"Usage: {prog} --check <FILE>..."
    if opts.keyed:
        return f"Usage: {prog} --keyed <FILE>..."
    return f"Usage: {prog} [OPTIONS] [FILE]..."


def clap_error(msg, opts=None, prog=None, usage=None):
    if usage is None and opts is not None and prog is not None:
        usage = usage_for(opts, prog)
    text = f"error: {msg}\n"
    if usage:
        text += f"\n{usage}\n"
    text += "\nFor more information, try '--help'.\n"
