import os
import sys
import struct

MASK32 = 0xFFFFFFFF
IV = [
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A,
    0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19,
]
MSG_PERMUTATION = [2, 6, 3, 10, 7, 0, 4, 13, 1, 11, 12, 5, 9, 14, 15, 8]
CHUNK_LEN = 1024
BLOCK_LEN = 64
OUT_LEN = 32
KEY_LEN = 32
CHUNK_START = 1
CHUNK_END = 2
PARENT = 4
ROOT = 8
KEYED_HASH = 16
DERIVE_KEY_CONTEXT = 32
DERIVE_KEY_MATERIAL = 64
HEX = b"0123456789abcdef"


def _rotr32(x, n):
    return ((x >> n) | ((x << (32 - n)) & MASK32)) & MASK32


def _g(v, a, b, c, d, mx, my):
    v[a] = (v[a] + v[b] + mx) & MASK32
    v[d] = _rotr32(v[d] ^ v[a], 16)
    v[c] = (v[c] + v[d]) & MASK32
    v[b] = _rotr32(v[b] ^ v[c], 12)
    v[a] = (v[a] + v[b] + my) & MASK32
    v[d] = _rotr32(v[d] ^ v[a], 8)
    v[c] = (v[c] + v[d]) & MASK32
    v[b] = _rotr32(v[b] ^ v[c], 7)


def _round(v, m):
    _g(v, 0, 4, 8, 12, m[0], m[1])
    _g(v, 1, 5, 9, 13, m[2], m[3])
    _g(v, 2, 6, 10, 14, m[4], m[5])
    _g(v, 3, 7, 11, 15, m[6], m[7])
    _g(v, 0, 5, 10, 15, m[8], m[9])
    _g(v, 1, 6, 11, 12, m[10], m[11])
    _g(v, 2, 7, 8, 13, m[12], m[13])
    _g(v, 3, 4, 9, 14, m[14], m[15])


def _compress(cv, block_words, counter, block_len, flags):
    v = list(cv) + IV[:4] + [counter & MASK32, (counter >> 32) & MASK32, block_len, flags]
    m = list(block_words)
    for _ in range(7):
        _round(v, m)
        m = [m[i] for i in MSG_PERMUTATION]
    return ([(v[i] ^ v[i + 8]) & MASK32 for i in range(8)] +
            [(v[i + 8] ^ cv[i]) & MASK32 for i in range(8)])


def _words_from_block(block):
    if len(block) != BLOCK_LEN:
        block = block + b"\0" * (BLOCK_LEN - len(block))
    return list(struct.unpack("<16I", block))


def _words_from_key(key):
    return list(struct.unpack("<8I", key))


def _words_to_bytes(words):
    return struct.pack("<%dI" % len(words), *words)


class _Node:
    __slots__ = ("cv", "block_words", "counter", "block_len", "flags")

    def __init__(self, cv, block_words, counter, block_len, flags):
        self.cv = cv
        self.block_words = block_words
        self.counter = counter
        self.block_len = block_len
        self.flags = flags

    def chaining_value(self):
        return _compress(self.cv, self.block_words, self.counter, self.block_len, self.flags)[:8]

    def root_output(self, seek, length):
        if length == 0:
            return b""
        out = bytearray()
        block_counter = seek // BLOCK_LEN
        offset = seek % BLOCK_LEN
        while len(out) < length:
            words = _compress(self.cv, self.block_words, block_counter, self.block_len, self.flags | ROOT)
            block = _words_to_bytes(words)
            piece = block[offset:]
            need = length - len(out)
            out.extend(piece[:need])
            block_counter += 1
            offset = 0
        return bytes(out)


def _chunk_node(chunk, chunk_index, key_words, flags):
    cv = list(key_words)
    if not chunk:
        return _Node(cv, _words_from_block(b""), chunk_index, 0, flags | CHUNK_START | CHUNK_END)
    pos = 0
    first = True
    total = len(chunk)
    while pos < total:
        block = chunk[pos:pos + BLOCK_LEN]
        pos += len(block)
        block_flags = flags
        if first:
            block_flags |= CHUNK_START
        if pos >= total:
            block_flags |= CHUNK_END
            return _Node(cv, _words_from_block(block), chunk_index, len(block), block_flags)
        cv = _compress(cv, _words_from_block(block), chunk_index, BLOCK_LEN, block_flags)[:8]
        first = False
    raise AssertionError("unreachable")


def _parent_node(left_cv, right_cv, key_words, flags):
    block = _words_to_bytes(left_cv + right_cv)
    return _Node(list(key_words), _words_from_block(block), 0, BLOCK_LEN, flags | PARENT)


def _subtree_node(data, start_chunk, key_words, flags):
    chunks = (len(data) + CHUNK_LEN - 1) // CHUNK_LEN
    if chunks <= 1:
        return _chunk_node(data, start_chunk, key_words, flags)
    # BLAKE3's tree groups chunks into powers of two. Split at the largest
    # power of two strictly smaller than the number of chunks.
    split_chunks = 1 << ((chunks - 1).bit_length() - 1)
    split_at = split_chunks * CHUNK_LEN
    left = _subtree_node(data[:split_at], start_chunk, key_words, flags)
    right = _subtree_node(data[split_at:], start_chunk + split_chunks, key_words, flags)
    return _parent_node(left.chaining_value(), right.chaining_value(), key_words, flags)


def _blake3_output(data, length=OUT_LEN, seek=0, key=None, flags=0):
    key_words = IV[:] if key is None else _words_from_key(key)
    root = _subtree_node(data, 0, key_words, flags)
    return root.root_output(seek, length)


def blake3_hash(data, length=OUT_LEN, seek=0):
    return _blake3_output(data, length, seek, None, 0)


def blake3_keyed_hash(key, data, length=OUT_LEN, seek=0):
    return _blake3_output(data, length, seek, key, KEYED_HASH)


