def missing_value(opt_display):
    write_stderr(f"error: a value is required for '{opt_display}' but none was supplied\n\nFor more information, try '--help'.\n".encode())
    return 2


def parse_args(argv):
    prog = os.path.basename(argv[0]) or "executable"
    opts = Options()
    i = 1
    parsing_opts = True
    while i < len(argv):
        arg = argv[i]
        if parsing_opts and arg == "--":
            parsing_opts = False
            i += 1
            continue
        if parsing_opts and arg in ("-h", "--help"):
            write_stdout((long_help(prog) if arg == "--help" else short_help(prog)).encode())
            return None, 0
        if parsing_opts and arg in ("-V", "--version"):
            write_stdout(b"b3sum 1.8.4\n")
            return None, 0
        if parsing_opts and arg == "--keyed":
            opts.keyed = True
        elif parsing_opts and (arg == "--derive-key" or arg.startswith("--derive-key=")):
            if arg == "--derive-key":
                if i + 1 >= len(argv):
                    return None, missing_value("--derive-key <CONTEXT>")
                i += 1
                opts.derive_key = argv[i]
            else:
                opts.derive_key = arg.split("=", 1)[1]
        elif parsing_opts and (arg == "--length" or arg.startswith("--length=")):
            if arg == "--length":
                if i + 1 >= len(argv):
                    return None, missing_value("--length <LEN>")
                i += 1
                val = argv[i]
            else:
                val = arg.split("=", 1)[1]
            n, err = parse_uint(val, "--length <LEN>", prog, opts)
            if err is not None:
                return None, err
            opts.length = n
            opts.length_explicit = True
        elif parsing_opts and arg.startswith("-l") and arg != "-":
            if arg == "-l":
                if i + 1 >= len(argv):
                    return None, missing_value("--length <LEN>")
                i += 1
                val = argv[i]
            else:
                val = arg[2:]
            n, err = parse_uint(val, "--length <LEN>", prog, opts)
            if err is not None:
                return None, err
            opts.length = n
            opts.length_explicit = True
        elif parsing_opts and (arg == "--seek" or arg.startswith("--seek=")):
            if arg == "--seek":
                if i + 1 >= len(argv):
                    return None, missing_value("--seek <SEEK>")
                i += 1
                val = argv[i]
            else:
                val = arg.split("=", 1)[1]
            n, err = parse_uint(val, "--seek <SEEK>", prog, opts)
            if err is not None:
                return None, err
            opts.seek = n
            opts.seek_explicit = True
        elif parsing_opts and (arg == "--num-threads" or arg.startswith("--num-threads=")):
            if arg == "--num-threads":
                if i + 1 >= len(argv):
                    return None, missing_value("--num-threads <NUM>")
                i += 1
                val = argv[i]
            else:
                val = arg.split("=", 1)[1]
            n, err = parse_uint(val, "--num-threads <NUM>", prog, opts)
            if err is not None:
                return None, err
            opts.num_threads = n
        elif parsing_opts and arg == "--no-mmap":
            opts.no_mmap = True
        elif parsing_opts and arg == "--no-names":
            opts.no_names = True
        elif parsing_opts and arg == "--raw":
            opts.raw = True
        elif parsing_opts and arg == "--tag":
            opts.tag = True
        elif parsing_opts and arg in ("-c", "--check"):
            opts.check = True
        elif parsing_opts and arg == "--quiet":
            opts.quiet = True
        elif parsing_opts and arg.startswith("-") and arg != "-":
            write_stderr(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: {prog} [OPTIONS] [FILE]...\n\nFor more information, try '--help'.\n".encode())
            return None, 2
        else:
            opts.files.append(arg)
        i += 1

    # Cross-argument validation, in the order observed from clap.
    if opts.keyed and opts.derive_key is not None:
        return None, clap_error("the argument '--keyed' cannot be used with '--derive-key <CONTEXT>'", opts, prog)
    if opts.check and opts.keyed:
        return None, clap_error("the argument '--check' cannot be used with '--keyed'", opts, prog)
    if opts.check and opts.derive_key is not None:
        return None, clap_error("the argument '--check' cannot be used with '--derive-key <CONTEXT>'", opts, prog)
    if opts.check and opts.length_explicit:
        return None, clap_error("the argument '--check' cannot be used with '--length <LEN>'", opts, prog)
    if opts.check and opts.no_names:
        return None, clap_error("the argument '--check' cannot be used with '--no-names'", opts, prog)
    if opts.check and opts.raw:
        return None, clap_error("the argument '--check' cannot be used with '--raw'", opts, prog)
    if opts.check and opts.tag:
        return None, clap_error("the argument '--check' cannot be used with '--tag'", opts, prog)
    if opts.quiet and not opts.check:
        write_stderr(f"error: the following required arguments were not provided:\n  --check\n\nUsage: {prog} --check --quiet <FILE>...\n\nFor more information, try '--help'.\n".encode())
        return None, 2
    if opts.keyed and not opts.files:
        write_stderr(f"error: the following required arguments were not provided:\n  <FILE>...\n\nUsage: {prog} --keyed <FILE>...\n\nFor more information, try '--help'.\n".encode())
        return None, 2
    return opts, None


def read_input_file(name_bytes):
    if name_bytes == b"-":
        return sys.stdin.buffer.read()
    with open(name_bytes, "rb") as f:
        return f.read()


def digest_data(data, opts, key):
    if key is not None:
        return blake3_keyed_hash(key, data, opts.length, opts.seek)
    if opts.derive_key is not None:
        return blake3_derive_key(opts.derive_key, data, opts.length, opts.seek)
    return blake3_hash(data, opts.length, opts.seek)


def output_hash(digest, name_bytes, opts):
    if opts.raw:
        write_stdout(digest)
        return
    h = hex_encode(digest)
    if opts.no_names:
        write_stdout(h + b"\n")
    elif opts.tag:
        en = escape_name(name_bytes)
        prefix = b"\\" if en.startswith(b"\\") else b""
        # escape_name already includes the leading marker; for BSD style it goes
        # before BLAKE3, not inside the filename.
        if prefix:
            en_inner = en[1:]
            write_stdout(b"\\BLAKE3 (" + en_inner + b") = " + h + b"\n")
        else:
            write_stdout(b"BLAKE3 (" + en + b") = " + h + b"\n")
    else:
        en = escape_name(name_bytes)
        write_stdout(en[:1] + h + b"  " + en[1:] + b"\n" if en.startswith(b"\\") else h + b"  " + en + b"\n")


def run_hash_mode(opts):
    files = opts.files if opts.files else ["-"]
    if opts.raw and len(files) > 1:
        write_stderr(b"Error: Only one filename can be provided when using --raw\n")
        return 1
    key = None
    if opts.keyed:
        key_material = sys.stdin.buffer.read()
        if len(key_material) < KEY_LEN:
            write_stderr(f"Error: expected 32 key bytes from stdin, found {len(key_material)}\n".encode())
            return 1
        if len(key_material) > KEY_LEN:
            write_stderr(b"Error: read more than 32 key bytes from stdin\n")
            return 1
        key = key_material
    rc = 0
    for f in files:
        name_bytes = os.fsencode(f)
        if opts.keyed and name_bytes == b"-":
            write_stderr(b"b3sum: -: Cannot open `-` in keyed mode\n")
            rc = 1
            continue
        try:
            data = read_input_file(name_bytes)
            digest = digest_data(data, opts, key)
            output_hash(digest, name_bytes, opts)
        except OSError as e:
            write_stderr(b"b3sum: " + name_bytes + b": " + os_error_text(e).encode() + b"\n")
            rc = 1
    return rc


def parse_check_line(line):
    # Remove LF and an optional preceding CR.
    if line.endswith(b"\n"):
        line = line[:-1]
    if line.endswith(b"\r"):
        line = line[:-1]
    escaped = False
    if line.startswith(b"\\"):
        escaped = True
        line = line[1:]
    # GNU-style: 64 lowercase hex chars, two spaces, filename.
    if len(line) >= 66 and line[64:66] == b"  ":
        h = line[:64]
        name = line[66:]
        if escaped:
            name = unescape_name(name)
            if name is None:
                return ("format", None, None)
        if name == b"":
            return ("empty", None, None)
        return ("ok", h, name)
    # BSD-style: BLAKE3 (filename) = hash. Find the last separator so ')' may
    # appear in filenames.
    sep = b") = "
    if line.startswith(b"BLAKE3 ("):
        idx = line.rfind(sep)
        if idx >= len(b"BLAKE3 ("):
            name = line[len(b"BLAKE3 ("):idx]
            h = line[idx + len(sep):]
            if escaped:
                name = unescape_name(name)
                if name is None:
                    return ("format", None, None)
            if name == b"":
                return ("empty", None, None)
            return ("ok", h, name)
    return ("format", None, None)


def check_one(name, expected_hex, opts):
    display = escape_name(name)
    try:
        expected = lowercase_hex_to_bytes(expected_hex)
    except ValueError as e:
        write_stderr(b"b3sum: Invalid hash length\n" if str(e) == "length" else b"b3sum: Invalid hex\n")
        return False
    subopts = Options()
    subopts.length = 32
    subopts.seek = opts.seek
    try:
        data = read_input_file(name)
        actual = blake3_hash(data, 32, opts.seek)
    except OSError as e:
        write_stdout(display + b": FAILED (" + os_error_text(e).encode() + b")\n")
        return False
    if actual == expected:
        if not opts.quiet:
            write_stdout(display + b": OK\n")
        return True
    write_stdout(display + b": FAILED\n")
    return False


def run_check_mode(opts):
    checkfiles = opts.files if opts.files else ["-"]
    failures = 0
    open_error = False
    for cf in checkfiles:
        cf_bytes = os.fsencode(cf)
        try:
            if cf_bytes == b"-":
                lines = sys.stdin.buffer.readlines()
            else:
                with open(cf_bytes, "rb") as f:
                    lines = f.readlines()
        except OSError as e:
            write_stderr(b"Error: " + os_error_text(e).encode() + b"\n")
            open_error = True
            continue
        for line in lines:
            kind, h, name = parse_check_line(line)
            if kind == "ok":
                if not check_one(name, h, opts):
                    failures += 1
            elif kind == "empty":
                write_stderr(b"b3sum: empty file path\n")
                failures += 1
            else:
                write_stderr(b"b3sum: Invalid check line format\n")
                failures += 1
    if failures:
        noun = b"checksum" if failures == 1 else b"checksums"
        verb = b"did" if failures == 1 else b"did"
        write_stderr(b"b3sum: WARNING: " + str(failures).encode() + b" computed " + noun + b" " + verb + b" NOT match\n")
    return 1 if failures or open_error else 0


def main(argv):
    opts, code = parse_args(argv)
    if code is not None:
        return code
    if opts.check:
        return run_check_mode(opts)
    return run_hash_mode(opts)


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv))
    except BrokenPipeError:
        try:
            sys.stderr.close()
        finally:
            raise SystemExit(1)
